<script setup lang="ts">
import { computed, ref } from 'vue'
import { ApiError, type Api, type Order, type RouteSnapshot } from './api'
const props = defineProps<{ api: Api; role: string }>()
const emit = defineEmits<{ expired: [] }>()
const canEdit = computed(() => ['ADMIN', 'OPERATOR'].includes(props.role))
const orders = ref<Order[]>([]); const page = ref(0); const total = ref(0); const chosen = ref<Order[]>([])
const routeId = ref(''); const route = ref<RouteSnapshot | null>(null); const sequence = ref<string[]>([])
const distance = ref(''); const busy = ref(false); const error = ref(''); const notice = ref('')
async function run(fn: () => Promise<void>) { busy.value = true; error.value = ''; notice.value = ''; try { await fn() } catch (e) { if (e instanceof ApiError && e.problem.status === 401) emit('expired'); error.value = e instanceof Error ? e.message : 'Não foi possível concluir a operação.' } finally { busy.value = false } }
async function load(n = page.value) { await run(async () => { const p = await props.api.list(n); page.value = n; orders.value = p.items; total.value = p.totalItems }) }
if (canEdit.value) void load()
function toggle(o: Order, checked: boolean) { if (!checked) { chosen.value = chosen.value.filter(x => x.orderId !== o.orderId); return } if (chosen.value.length >= 10) { error.value = 'Selecione no máximo 10 pedidos.'; return } if (chosen.value.length && (chosen.value[0].originId !== o.originId || chosen.value[0].storeId !== o.storeId)) { error.value = 'Os pedidos devem ter a mesma origem e loja.'; return } error.value = ''; chosen.value.push(o) }
function move(list: string[], index: number, delta: number) { const target = index + delta; if (target < 0 || target >= list.length) return; [list[index], list[target]] = [list[target], list[index]] }
const chosenIds = computed(() => chosen.value.map(o => o.orderId))
function moveChosen(index: number, delta: number) { const target = index + delta; if (target >= 0 && target < chosen.value.length) [chosen.value[index], chosen.value[target]] = [chosen.value[target], chosen.value[index]] }
async function suggest() { await run(async () => { const s = await props.api.suggest(chosen.value[0].originId, chosenIds.value); if (s.orderedOrderIds.length !== chosen.value.length || new Set(s.orderedOrderIds).size !== chosen.value.length || s.orderedOrderIds.some(id => !chosenIds.value.includes(id))) throw new Error('Sugestão inválida recebida do servidor.'); chosen.value = s.orderedOrderIds.map(id => chosen.value.find(o => o.orderId === id)!); distance.value = s.estimatedDistanceKm; notice.value = 'Sugestão aplicada; você ainda pode alterar a ordem.' }) }
function setRoute(r: RouteSnapshot) { route.value = r; routeId.value = r.routeId; sequence.value = [...r.orderIds] }
async function create() { await run(async () => { setRoute(await props.api.createRoute(chosen.value[0].originId, chosenIds.value)); notice.value = 'Rota criada.' }) }
async function lookup() { await run(async () => { setRoute(await props.api.getRoute(routeId.value.trim())) }) }
async function assign() { if (route.value) await run(async () => { setRoute(await props.api.assignRoute(route.value!.routeId)); notice.value = 'Rota atribuída.' }) }
async function start() { if (route.value) await run(async () => { setRoute(await props.api.startRoute(route.value!.routeId)); notice.value = 'Rota iniciada.' }) }
async function saveOrder() { if (route.value) await run(async () => { setRoute(await props.api.reorderRoute(route.value!.routeId, sequence.value)); notice.value = 'Ordem atualizada.' }) }
</script>
<template><section><div class="page-head"><div><div class="eyebrow">OPERAÇÃO / ROTAS</div><h1>Rotas</h1><p>Consulte uma rota pelo ID<span v-if="canEdit"> ou planeje até 10 pedidos confirmados</span>.</p></div></div>
<p v-if="busy" role="status">Carregando…</p><div v-if="error" class="alert error" role="alert">{{ error }}</div><div v-if="notice" class="alert success" role="status">{{ notice }}</div>
<div class="card"><h2>Consultar rota</h2><form @submit.prevent="lookup"><label>ID da rota<input v-model="routeId" required></label><button class="secondary" :disabled="busy">Consultar</button></form></div>
<div v-if="route" class="card route-card"><h2>Rota {{ route.routeId }}</h2><p>Status: {{ route.status }} · Loja: {{ route.storeId }} · Origem: {{ route.originId }}</p><p>Motorista: {{ route.driverId || 'Não atribuído' }} · Veículo: {{ route.vehicleId || 'Não atribuído' }}</p><p>Início: {{ route.startedAt || 'Não iniciado' }}</p><h3>Paradas</h3><ol><li v-for="(id, i) in sequence" :key="id"><span class="mono">{{ id }}</span> <template v-if="canEdit && ['PLANNED','ASSIGNED'].includes(route.status)"><button class="link" :disabled="busy || i === 0" :aria-label="`Subir parada ${id}`" @click="move(sequence, i, -1)">↑</button><button class="link" :disabled="busy || i === sequence.length - 1" :aria-label="`Descer parada ${id}`" @click="move(sequence, i, 1)">↓</button></template></li></ol><template v-if="canEdit"><button v-if="['PLANNED','ASSIGNED'].includes(route.status)" class="secondary" :disabled="busy" @click="saveOrder">Salvar ordem</button> <button v-if="route.status === 'PLANNED'" class="secondary" :disabled="busy" @click="assign">Atribuir motorista e veículo</button> <button v-if="route.status === 'ASSIGNED'" class="primary" :disabled="busy" @click="start">Iniciar rota</button></template></div>
<div v-if="canEdit" class="card route-card"><h2>Planejar rota</h2><p>Selecione pedidos confirmados da mesma origem e loja. Uma sugestão indisponível não impede a ordem manual.</p><p v-if="!busy && !orders.some(o => o.status === 'CONFIRMED')">Nenhum pedido confirmado nesta página.</p><div v-for="o in orders.filter(o => o.status === 'CONFIRMED')" :key="o.orderId"><label class="choice"><input type="checkbox" :checked="chosenIds.includes(o.orderId)" :disabled="busy" @change="toggle(o, ($event.target as HTMLInputElement).checked); ($event.target as HTMLInputElement).checked = chosenIds.includes(o.orderId)">{{ o.recipientName }} · {{ o.orderId }} · {{ o.totalWeightKg }} kg</label></div><div class="pagination"><button class="secondary" :disabled="busy || page === 0" @click="load(page-1)">Anterior</button><span>Página {{ page+1 }}</span><button class="secondary" :disabled="busy || (page+1)*20 >= total" @click="load(page+1)">Próxima</button></div><h3>Ordem selecionada ({{ chosen.length }}/10)</h3><ol><li v-for="(o,i) in chosen" :key="o.orderId">{{ o.recipientName }} · <span class="mono">{{ o.orderId }}</span> <button class="link" :disabled="busy || i===0" :aria-label="`Subir pedido ${o.orderId}`" @click="moveChosen(i,-1)">↑</button><button class="link" :disabled="busy || i===chosen.length-1" :aria-label="`Descer pedido ${o.orderId}`" @click="moveChosen(i,1)">↓</button><button class="link" :disabled="busy" @click="toggle(o,false)">Remover</button></li></ol><p v-if="distance">Última distância sugerida: {{ distance }} km</p><button class="secondary" :disabled="busy || !chosen.length" @click="suggest">Sugerir ordem</button> <button class="primary" :disabled="busy || !chosen.length" @click="create">Criar rota</button></div></section></template>
